    pub fn use_current_buena_password_guess(&mut self) -> Result<RuntimeSpecialRoutineUse> {
        self.use_buena_password(None)?;
        let guess = self
            .session
            .state
            .script_runtime
            .variables
            .get("_buena_password")
            .cloned()
            .context("BuenasPassword did not produce _buena_password")?;
        self.use_buena_password(Some(guess))
    }

