    pub fn set_script_runtime_variable(
        &mut self,
        key: &str,
        value: impl Into<String>,
    ) -> Result<()> {
        self.session
            .state
            .script_runtime
            .variables
            .insert(key.to_string(), value.into());
        self.runtime
            .validate_save_state_for_runtime_pack(&self.session.state)
            .with_context(|| format!("validate script runtime variable {key}"))?;
        Ok(())
    }

