        let use_rod = session
            .use_bag_fishing_rod_in_field(&runtime, "GOOD_ROD")
            .expect("use good rod item");

        assert_eq!(use_rod.item_use.item_id, "GOOD_ROD");
        assert!(!use_rod.item_use.consumed);
        assert_eq!(use_rod.rod, ROD_GOOD);
